import { gql } from "~/gql";

// Operation names are global across erxes; keep the plugin prefix. gql() is
// generated by codegen — write documents as static strings (no `${}`), and
// let Apollo hooks infer their types from the document.

export const SETS_QUERY = gql(`
  query homeworkSets(
    $scope: HomeworkScope!
    $search: String
    $subject: String
    $grade: Int
    $setType: HomeworkSetType
    $difficulty: HomeworkDifficulty
    $sort: HomeworkSort
    $limit: Int
    $offset: Int
  ) {
    homeworkSets(
      scope: $scope
      search: $search
      subject: $subject
      grade: $grade
      setType: $setType
      difficulty: $difficulty
      sort: $sort
      limit: $limit
      offset: $offset
    ) {
      totalCount
      list {
        _id
        title
        subject
        grade
        topic
        setType
        difficulty
        visibility
        copyCount
        ratingCount
        ratingAverage
        isOwner
        questions {
          id
        }
        author {
          userId
          fullName
          school
        }
      }
    }
  }
`);

export const SET_QUERY = gql(`
  query homeworkSet($_id: String!) {
    homeworkSet(_id: $_id) {
      _id
      title
      subject
      grade
      topic
      curriculumUnit
      setType
      difficulty
      sourceType
      visibility
      copyCount
      ratingCount
      ratingAverage
      myRating
      isOwner
      createdAt
      updatedAt
      questions {
        id
        type
        prompt
        options
        answer
        explanation
        points
      }
      author {
        userId
        fullName
        school
      }
    }
  }
`);

export const PROFILE_QUERY = gql(`
  query homeworkProfile {
    homeworkProfile {
      userId
      fullName
      school
      district
      subjects
      grades
    }
  }
`);

export const CONFIG_QUERY = gql(`
  query homeworkConfig {
    homeworkConfig {
      aiEnabled
      model
      maxPdfBytes
    }
  }
`);

export const GENERATE_MUTATION = gql(`
  mutation homeworkGenerate($input: HomeworkGenerationInput!) {
    homeworkGenerate(input: $input) {
      title
      topicSummary
      mocked
      inClass {
        id
        type
        prompt
        options
        answer
        explanation
        points
      }
      homework {
        id
        type
        prompt
        options
        answer
        explanation
        points
      }
    }
  }
`);

export const SAVE_GENERATION_MUTATION = gql(`
  mutation homeworkGenerationSave(
    $requestId: String!
    $input: HomeworkGenerationInput!
    $generated: HomeworkGeneratedInput!
    $visibility: HomeworkVisibility!
  ) {
    homeworkGenerationSave(
      requestId: $requestId
      input: $input
      generated: $generated
      visibility: $visibility
    ) {
      inClassSetId
      homeworkSetId
    }
  }
`);

export const SET_UPDATE_MUTATION = gql(`
  mutation homeworkSetUpdate($_id: String!, $input: HomeworkSetInput!) {
    homeworkSetUpdate(_id: $_id, input: $input) {
      _id
      title
      subject
      grade
      topic
      curriculumUnit
      difficulty
      visibility
      updatedAt
      questions {
        id
        type
        prompt
        options
        answer
        explanation
        points
      }
    }
  }
`);

export const SET_REMOVE_MUTATION = gql(`
  mutation homeworkSetRemove($_id: String!) {
    homeworkSetRemove(_id: $_id)
  }
`);

export const SET_COPY_MUTATION = gql(`
  mutation homeworkSetCopy($_id: String!) {
    homeworkSetCopy(_id: $_id) {
      _id
    }
  }
`);

export const SET_RATE_MUTATION = gql(`
  mutation homeworkSetRate($_id: String!, $stars: Int!) {
    homeworkSetRate(_id: $_id, stars: $stars) {
      _id
      ratingCount
      ratingAverage
      myRating
    }
  }
`);

export const PROFILE_UPDATE_MUTATION = gql(`
  mutation homeworkProfileUpdate($input: HomeworkProfileInput!) {
    homeworkProfileUpdate(input: $input) {
      userId
      fullName
      school
      district
      subjects
      grades
    }
  }
`);
